/// <summary>
/// One page of a handheld master-data feed - see HSMobileOpsSkuPageService::getSkuPage.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSkuPageRequest
{
    str dataAreaId;
    str feed;
    str afterKey;
    str changedSinceUtc;
    int pageSize;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public str parmDataAreaId(str _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('Feed')]
public str parmFeed(str _value = feed)
{
    feed = _value;
    return feed;
}

[DataMemberAttribute('AfterKey')]
public str parmAfterKey(str _value = afterKey)
{
    afterKey = _value;
    return afterKey;
}

[DataMemberAttribute('ChangedSinceUtc')]
public str parmChangedSinceUtc(str _value = changedSinceUtc)
{
    changedSinceUtc = _value;
    return changedSinceUtc;
}

[DataMemberAttribute('PageSize')]
public int parmPageSize(int _value = pageSize)
{
    pageSize = _value;
    return pageSize;
}
